package com.wandertrace.service;
import com.wandertrace.exception.AccessDeniedException;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class TripAccessServiceTest { private JdbcTemplate db; private TripAccessService access; private final UUID user=UUID.randomUUID(),trip=UUID.randomUUID(); @BeforeEach void setup(){db=mock(JdbcTemplate.class);access=new TripAccessService(db);} @Test void editorCanEdit(){when(db.queryForList(anyString(),any(),any())).thenReturn(List.of(Map.of("role","EDITOR")));assertDoesNotThrow(()->access.requireEdit(user,trip));} @Test void viewerCannotEdit(){when(db.queryForList(anyString(),any(),any())).thenReturn(List.of(Map.of("role","VIEWER")));assertThrows(AccessDeniedException.class,()->access.requireEdit(user,trip));} @Test void nonMemberCannotView(){when(db.queryForList(anyString(),any(),any())).thenReturn(List.of());assertThrows(AccessDeniedException.class,()->access.requireView(user,trip));} }
